import fs from "node:fs/promises";
import path from "node:path";
import { createCalaKnowledgeClient } from "../lib/cala";

async function main() {
  const query = process.argv[2] ?? "What are the most relevant historical periods of Spain";

  const apiKey = process.env.CALA_API_KEY;
  if (!apiKey) {
    throw new Error("Set CALA_API_KEY in your environment (see .env.local.example) before running this script.");
  }

  const cala = createCalaKnowledgeClient(apiKey);
  const results = await cala.knowledgeSearch(query);

  const output = { query, results };

  const targetPath = path.join(process.cwd(), "data", "knowledge-search.json");
  await fs.writeFile(targetPath, `${JSON.stringify(output, null, 2)}\n`, "utf8");

  console.log(`Wrote ${results.length} results to ${targetPath}`);
}

main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});

