    """Resolves a title for a claim via Cala's provenance chain: the first cited
    context's source document name (falling back to its publisher name)."""
    for ref_id in references:
        context = context_by_id.get(ref_id)
        if not context:
            continue
        for origin in context.get("origins", []):
            document_name = origin.get("document", {}).get("name")
            if document_name:
                return document_name
            source_name = origin.get("source", {}).get("name")
            if source_name:
                return source_name
    return ""


