#!/usr/bin/env python3
"""
Runs a Cala knowledge_search query for historical events and saves results as JSON.

Each output record captures:
  - title: the title of the cited source document, resolved from Cala's provenance
           chain (explainability[i].references -> context[j].id -> origins[k].document.name),
           falling back to the publisher name, then "".
  - event: a short event label, resolved by matching Cala's own extracted Event-type
           entities (from the "entities" array) against the claim's text. Falls back to
           the text preceding the timeline range when no Event entity matches.
  - fact: the underlying supporting claim from Cala's explainability trace
  - timeline: the historical period/date range the fact belongs to
  - source_url: the cited source document's URL, from the same provenance chain as title

Usage:
  Put CALA_API_KEY=your-key in a .env file at the project root, then:
  python3 backend/knowledge_search_events.py "What are the most significant historical events in Spain's history?"
"""

import argparse
import json
import os
import re
import sys
import urllib.request

CALA_MCP_URL = "https://api.cala.ai/mcp/"


def load_dotenv(path: str) -> None:
    """Minimal .env loader: sets os.environ for KEY=VALUE lines not already set."""
    if not os.path.isfile(path):
        return
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line or line.startswith("#") or "=" not in line:
                continue
            key, _, value = line.partition("=")
            key = key.strip()
            value = value.strip().strip('"').strip("'")
            if key and key not in os.environ:
                os.environ[key] = value


# Matches a leading date/era range like "(c. 50,000 BC - 1,100 BC)" or "(711-1492)".
TIMELINE_PATTERN = re.compile(
    r"\(([^()]*?\b(?:BC|AD|century|present)?[^()]*?\d[^()]*?)\)"
)


def call_cala_knowledge_search(query: str, api_key: str) -> dict:
    """Calls the Cala MCP server's knowledge_search tool over HTTP."""
    payload = {
        "jsonrpc": "2.0",
        "id": 1,
        "method": "tools/call",
        "params": {
            "name": "knowledge_search",
            "arguments": {
                "input": query,
                "explainability": True,
                "return_entities": True,
            },
        },
    }

    req = urllib.request.Request(
        CALA_MCP_URL,
        data=json.dumps(payload).encode("utf-8"),
        headers={
            "Content-Type": "application/json",
            "Accept": "application/json, text/event-stream",
            "X-API-KEY": api_key,
        },
        method="POST",
    )

    with urllib.request.urlopen(req, timeout=60) as resp:
        body = resp.read().decode("utf-8")

    # Cala's MCP endpoint may respond as SSE ("event: message\ndata: {...}") or plain JSON.
    if body.lstrip().startswith("event:"):
        data_lines = [
            line[len("data:"):].strip()
            for line in body.splitlines()
            if line.startswith("data:")
        ]
        body = data_lines[-1] if data_lines else body

    result = json.loads(body)
    if "error" in result:
        raise RuntimeError(f"Cala MCP error: {result['error']}")
    return result["result"]


def extract_timeline(text: str) -> str:
    match = TIMELINE_PATTERN.search(text)
    return match.group(1).strip() if match else ""


def resolve_source(references: list, context_by_id: dict) -> tuple:
    """Resolves (title, url) for a claim via Cala's provenance chain: the first cited
    context's source document name/url (falling back to its publisher name/url)."""
    for ref_id in references:
        context = context_by_id.get(ref_id)
        if not context:
            continue
        for origin in context.get("origins") or []:
            document = origin.get("document") or {}
            if document.get("name"):
                return document.get("name"), document.get("url", "")
            source = origin.get("source") or {}
            if source.get("name"):
                return source.get("name"), source.get("url", "")
    return "", ""


YEAR_PATTERN = re.compile(r"\b(\d{3,4})\b")

# Splits a claim's leading subject clause off from its trailing sourcing clause,
# e.g. "The Muslim conquest beginning in 711 [...] is documented in the medieval
# timeline fact." -> subject = "The Muslim conquest beginning in 711 [...]".
SUBJECT_CLAUSE_PATTERN = re.compile(
    r"^(.*?)\s+(?:is|are|was|were)\s+(?:documented|described|confirmed|listed|"
    r"recorded|noted|mentioned|detailed|supported|reflected|corroborated|"
    r"substantiated|backed|inferred|validated|established)\b",
    re.IGNORECASE,
)


def fallback_event_label(fact: str) -> str:
    """Derives a short label from the fact's subject clause when no Cala Event
    entity matches this claim: the text preceding its timeline range if present,
    otherwise the clause preceding its sourcing verb (e.g. 'is documented in...'),
    with the first year mentioned appended for context."""
    timeline_match = TIMELINE_PATTERN.search(fact)
    if timeline_match:
        label = fact[:timeline_match.start()].strip().rstrip(":;,-")
        if label:
            return label

    subject_match = SUBJECT_CLAUSE_PATTERN.match(fact)
    label = subject_match.group(1).strip() if subject_match else fact.rstrip(".").strip()

    year_match = YEAR_PATTERN.search(label) or YEAR_PATTERN.search(fact)
    if year_match and year_match.group(1) not in label:
        label = f"{label} ({year_match.group(1)})"

    return label


def resolve_event(fact: str, event_entities: list) -> str:
    """Resolves an event label by matching Cala's own extracted Event-type entities
    (their 'mentions') against this claim's text. Falls back to a derived label."""
    for entity in event_entities:
        for mention in entity.get("mentions") or []:
            if mention and mention.lower() in fact.lower():
                return entity.get("name", mention)
    return fallback_event_label(fact)


def build_records(mcp_result: dict) -> list:
    """Turns Cala's explainability entries into title/event/fact/timeline/source_url records."""
    content_blocks = mcp_result.get("content", [])
    tool_output = None
    for block in content_blocks:
        if block.get("type") == "text":
            tool_output = json.loads(block["text"])
            break
    if tool_output is None:
        raise RuntimeError("No text content block found in Cala MCP response")

    context_by_id = {ctx["id"]: ctx for ctx in tool_output.get("context", []) if "id" in ctx}
    event_entities = [
        entity for entity in (tool_output.get("entities") or [])
        if entity.get("entity_type") == "Event"
    ]

    records = []
    for item in tool_output.get("explainability", []):
        fact = item.get("content", "")
        references = item.get("references", [])
        title, source_url = resolve_source(references, context_by_id)
        records.append(
            {
                "title": title,
                "event": resolve_event(fact, event_entities),
                "fact": fact,
                "timeline": extract_timeline(fact),
                "source_url": source_url,
            }
        )
    return records


def main():
    parser = argparse.ArgumentParser(description="Run a Cala knowledge_search for historical events and save results as JSON.")
    parser.add_argument(
        "query",
        nargs="?",
        default="What are the most significant historical events in Spain's history?",
        help="Natural language query to send to Cala's knowledge_search tool.",
    )
    parser.add_argument(
        "-o", "--output",
        default=os.path.join(os.path.dirname(__file__), "..", "data", "knowledge-search-spain-2.json"),
        help="Path to write the resulting JSON file.",
    )
    args = parser.parse_args()

    load_dotenv(os.path.join(os.path.dirname(__file__), "..", ".env"))

    api_key = os.environ.get("CALA_API_KEY")
    if not api_key:
        print("Error: set CALA_API_KEY in the project's .env file before running this script.", file=sys.stderr)
        sys.exit(1)

    try:
        mcp_result = call_cala_knowledge_search(args.query, api_key)
        records = build_records(mcp_result)
    except Exception as exc:
        print(f"Error running Cala knowledge search: {exc}", file=sys.stderr)
        sys.exit(1)

    output = {
        "query": args.query,
        "results": records,
    }

    output_path = os.path.abspath(args.output)
    os.makedirs(os.path.dirname(output_path), exist_ok=True)
    with open(output_path, "w", encoding="utf-8") as f:
        json.dump(output, f, indent=2, ensure_ascii=False)

    print(f"Saved {len(records)} records to {output_path}")


if __name__ == "__main__":
    main()

